import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from the terms of its person's grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment, and whether
 *  its last statement bound it to n/a (the rate that would apply to it had ended: its due stays n/a), and
 *  the date it is deferred until (null when it was never deferred: see `isDeferred`), and how many proofs it has. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  statedNa: boolean;
  deferredUntil: string | null;
  proofs: number;
  log: string[];
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to (a PENDING claim is not bound; 'n/a' when it bound it to n/a); null when its due is live. */
export function fixedDue(c: Claim): string | null {
  if (c.due !== null) return c.due;
  if (!isBound(c)) return null;
  return c.statedNa ? 'n/a' : c.statedDue;
}

/** Whether a claim is deferred now: it is OPEN and the date it is deferred until is after the sheet's
 *  today. Until today reaches that date it counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Claim, today: string | undefined): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;
}

/** Whether a claim counts toward claimed and every live total, given the people's holds by person id
 *  and the sheet's today: only open (OPEN or PENDING) and SETTLED claims do, and an open claim dated within
 *  one of its person's holds does not, unless a statement binds it, nor does a deferred one. */
export function counts(c: Claim, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  return c.status === 'SETTLED'
    || (isOpen(c) && !isDeferred(c, today) && (isBound(c) || !heldOn(holds.get(c.personId), c.date)));
}

/** Whether its person's last statement binds a claim now: it was stated and is not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{ claims: Omit<Claim, 'log'>[]; logs: Record<string, string[]> }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/claims`,
      );
      return res.claims.map((c): Claim => ({ ...c, log: res.logs[String(c.id)] ?? [] }));
    },
  });
}

/** The sum of the amounts of those of these claims that count (given the people's holds by person id and
 *  the sheet's today), with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], holds: ReadonlyMap<number, Hold[]>, today: string | undefined): string {
  const cents = claims.filter((c) => counts(c, holds, today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A claim's status change (open, settle, approve, reject or void), shared by the single and the bulk actions. Every
 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
final class ClaimStatusChange {
    private ClaimStatusChange() {
    }

    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup);
    }

    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        if ("resettle".equals(action == null ? "" : action.trim())) {
            return resettle(id, cid, by, repository, periods, settings, audit, rollup);
        }
        String to;
        List<String> from;
        String event;
        switch (action == null ? "" : action.trim()) {
            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING"); event = "CLAIM_VOIDED"; }
            default -> throw new BadRequestException("no such action");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!from.contains(found.status())) {
            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
        // Four eyes: whoever opened a claim cannot settle it.
        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
            throw new BadRequestException("the user who opened a claim cannot settle it");
        }
        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
        if (to.equals("SETTLED") && found.deferred()) {
            throw new BadRequestException("a claim deferred until " + found.deferredUntil() + " cannot be settled");
        }
        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
        if (found.status().equals("PENDING") && !to.equals("VOID")) {
            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
            }
            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
                throw new BadRequestException("the user who opened a claim cannot approve it");
            }
        }
        String why = reason == null ? "" : reason.trim();
        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
            throw new BadRequestException("give a reason to reject the claim");
        }
        // A claim whose due is above the proof threshold in force on its date cannot be settled or approved
        // without a proof ('n/a' is above none); this is decided before the clerk limit.
        if (to.equals("SETTLED") && found.proofs() == 0) {
            BigDecimal threshold = settings.proofThreshold(id, LocalDate.parse(found.date()));
            BigDecimal now = repository.dueNow(id, found);
            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
                throw new BadRequestException("a claim with a due above the proof threshold needs a proof to be settled");
            }
        }
        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
        if (to.equals("SETTLED") && found.status().equals("OPEN")
                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
            BigDecimal limit = settings.clerkLimit(id);
            BigDecimal now = repository.dueNow(id, found);
            if (limit != null && now != null && now.compareTo(limit) > 0) {
                to = "PENDING";
                event = "CLAIM_PENDING";
            }
        }
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.changeStatus(id, cid, from, to)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
        }
        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
        String number = found.number();
        String openedBy = found.openedBy();
        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
            number = repository.numbersPerPeriod(id)
                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.date()))
                    : repository.number(id, cid);
            repository.openedBy(id, cid, by);
            openedBy = by;
        }
        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
        String due = null;
        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
        if (to.equals("SETTLED")) {
            BigDecimal now = repository.dueNow(id, found);
            repository.settleDue(id, cid, now);
            due = ClaimRepository.dueOf(now);
            tail = " due=" + (due == null ? "n/a" : due);
        }
        repository.log(id, cid, by);
        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
                found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs());
        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
        rollup.record(id, by, before);
        return changed;
    }

    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can re-settle a claim");
        }
        if (!found.status().equals("SETTLED")) {
            throw new BadRequestException("only a SETTLED claim can be re-settled");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false, found.proofs());
        BigDecimal now = repository.dueNow(id, live);
        Rollup.Snapshot before = rollup.take(id);
        repository.settleDue(id, cid, now);
        repository.log(id, cid, by);
        String old = found.due() == null ? "n/a" : found.due();
        String due = ClaimRepository.dueOf(now);
        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs());
        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
                + " old=" + old + " new=" + (due == null ? "n/a" : due));
        rollup.record(id, by, before);
        return changed;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.person.Hold;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
